function fnv1a(str, seed){
  var h=(0x811c9dc5 ^ (seed>>>0))>>>0;
  for(var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193)>>>0; }
  return h>>>0;
}
function fingerprint(item){
  var f=fnv1a(String(item), 0x1234) & 0xff;
  return f===0 ? 1 : f;
}
function cuckooCreate(buckets, bucketSize){
  if((buckets & (buckets-1))!==0 || buckets<2) throw new Error('BUCKETS_POW2');
  var b=[];
  for(var i=0;i<buckets;i++) b.push([]);
  return { m:buckets, b:(bucketSize||4), buckets:b, count:0 };
}
function idx1(item, m){ return fnv1a(String(item), 0) % m; }
function altIndex(i, fp, m){ return (i ^ (fnv1a(String(fp), 0x5bd1) % m)) % m; }
function cuckooInsert(cf, item){
  var fp=fingerprint(item);
  var i1=idx1(item, cf.m), i2=altIndex(i1, fp, cf.m);
  if(cf.buckets[i1].length<cf.b){ cf.buckets[i1].push(fp); cf.count++; return { ok:true, kicks:0 }; }
  if(cf.buckets[i2].length<cf.b){ cf.buckets[i2].push(fp); cf.count++; return { ok:true, kicks:0 }; }
  var i=Math.random()<0.5?i1:i2, cur=fp;
  for(var k=0;k<500;k++){
    var slot=Math.floor(Math.random()*cf.b);
    var evicted=cf.buckets[i][slot];
    cf.buckets[i][slot]=cur;
    cur=evicted;
    i=altIndex(i, cur, cf.m);
    if(cf.buckets[i].length<cf.b){ cf.buckets[i].push(cur); cf.count++; return { ok:true, kicks:k+1 }; }
  }
  return { ok:false, kicks:500 };
}
function cuckooContains(cf, item){
  var fp=fingerprint(item);
  var i1=idx1(item, cf.m), i2=altIndex(i1, fp, cf.m);
  return cf.buckets[i1].indexOf(fp)>=0 || cf.buckets[i2].indexOf(fp)>=0;
}
function cuckooDelete(cf, item){
  var fp=fingerprint(item);
  var i1=idx1(item, cf.m), i2=altIndex(i1, fp, cf.m);
  var p=cf.buckets[i1].indexOf(fp);
  if(p>=0){ cf.buckets[i1].splice(p,1); cf.count--; return true; }
  p=cf.buckets[i2].indexOf(fp);
  if(p>=0){ cf.buckets[i2].splice(p,1); cf.count--; return true; }
  return false;
}
function loadFactor(cf){ return cf.count/(cf.m*cf.b); }
